-- DISI rollback of Migration 050 (international benchmark expansion and probability-support audit).
-- database/release/sql/rollback-050.sql, generated by database/research/050/build.mjs from the same research files as the migration.
--
-- Use only if a production failure requires it. One transaction, guarded. It removes exactly what 050 added - the 2015 / 2016 benchmark
-- players, signings, population members and populations, the 050 rankings, the 050 outcome audits, outcomes and evidence, the two legacy
-- identities - restores the stored 041 model evaluation rows exactly, restores the 044 definition of disi_executive_overview() and the 045b
-- definition of disi_refresh_product_snapshots(), and refreshes the product snapshots once. The source rows stay as provenance.
--
-- The 026 evaluation guard seals ACTIVE rankings (a sealed point-in-time observation is never deleted by research). Restoring the exact
-- pre-050 state is the one sanctioned exception: inside this transaction only, the two guard triggers are disabled, exactly the 050
-- rankings are removed, and the triggers are enabled again before commit (proved below). 050 can be applied again after this rollback.

begin;

create temporary table _r050 on commit drop as
select $r050${"baseline":{"counts":{"benchmark_players":48,"benchmark_signings":48,"census_coverage_rows":10,"dodgers_audits":93,"dodgers_not_audited":127,"dodgers_players":220,"dodgers_signings":220,"dodgers_verified_mlb":47,"dodgers_verified_no_mlb":46,"functions":73,"known_costs":56,"known_spend_usd":"121700237.33","milestones":1073,"open_research_tasks":349,"outcome_audits":136,"outcomes":58,"player_evaluations":51,"players":268,"population_members":316,"signing_populations":17,"signings":268,"snapshot_generation":"6","sources":2472,"stints":1859,"tables":78,"transaction_assets":396,"transaction_events":213,"views":155,"war_rows":1880},"evaluation":[{"auc":null,"brier_score":"0.124032","brier_skill_vs_base_rate":"0","data_as_of_date":"2026-10-05","decision":"BASELINE_REFERENCE","evaluated_rows":59,"evaluation_current":true,"folds":5,"live_rows":59,"log_loss":"0.428292","model_key":"BASE_RATE","model_version":"outcome-probability-v1","positive_n":8,"target_key":"REACH_MLB_WITHIN_7_SEASONS","training_fingerprint":"683251fe2e7522fcd346cf6a26004e08"},{"auc":"0.564951","brier_score":"0.13927","brier_skill_vs_base_rate":"-0.12286","data_as_of_date":"2026-10-05","decision":"MODEL_NOT_SUPPORTED","evaluated_rows":59,"evaluation_current":true,"folds":5,"live_rows":59,"log_loss":"0.454953","model_key":"LOGISTIC_L2","model_version":"outcome-probability-v1","positive_n":8,"target_key":"REACH_MLB_WITHIN_7_SEASONS","training_fingerprint":"683251fe2e7522fcd346cf6a26004e08"},{"auc":"0.355392","brier_score":"0.142827","brier_skill_vs_base_rate":"-0.151533","data_as_of_date":"2026-10-05","decision":"MODEL_NOT_SUPPORTED","evaluated_rows":59,"evaluation_current":true,"folds":5,"live_rows":59,"log_loss":"0.843747","model_key":"POPULATION_STRATIFIED_RATE","model_version":"outcome-probability-v1","positive_n":8,"target_key":"REACH_MLB_WITHIN_7_SEASONS","training_fingerprint":"683251fe2e7522fcd346cf6a26004e08"}]},"dodgers_evaluations":[],"evaluation_041":[{"auc":null,"brier_score":0.124