g":"marcos-brito"}],"populations":["MLB-2015-PIPELINE-TOP30","MLB-2016-PIPELINE-TOP30"],"publication_slug":"mlb-pipeline-top-30-international-signings","refresh":{"new_md5":"7f0151fdcd496c50e16dc91b7758b7c0","old_md5":"4095c4c128ba03f27c359c4a5184ed9a"}}$r050$::jsonb as j;

-- ===========================================================================
-- 1. GUARDS
-- ===========================================================================

do $$
declare
  n int;
begin
  if (select count(*) from public.signing_populations where population_key in (select jsonb_array_elements_text(j -> 'populations') from _r050)) = 0 then
    raise exception 'rollback-050: Migration 050 is not applied';
  end if;
  -- later research must not depend on what is removed
  select count(*) into n from public.players pl
    where pl.slug in (select x ->> 'slug' from _r050, jsonb_array_elements(j -> 'new_players') x)
      and (exists (select 1 from public.player_season_stints s where s.player_id = pl.id)
        or exists (select 1 from public.development_milestones m where m.player_id = pl.id)
        or exists (select 1 from public.player_mlb_team_season_war w where w.player_id = pl.id or w.bref_id = pl.bref_id)
        or exists (select 1 from public.transaction_event_assets a where a.player_id = pl.id or a.mlb_id = pl.mlb_id::text)
        or exists (select 1 from public.player_network_relationships r where r.player_id = pl.id)
        or (select count(*) from public.signings s where s.player_id = pl.id) <> 1
        or (select count(*) from public.player_evaluations e where e.player_id = pl.id) <> 1);
  if n > 0 then
    raise exception 'rollback-050: later research depends on % of the 050 benchmark players; rollback refused', n;
  end if;
end $$;

-- ===========================================================================
-- 2. THE 050 RANKINGS (the one sanctioned removal of sealed rows)
-- ===========================================================================

create temporary table _r050_eval on commit drop as
select e.id from public.player_evaluations e
join public.scouting_publications pub on pub.id = e.publication_id and pub.publication_slug = (select j ->> 'publication_slug' from _r050)
join public.players pl on pl.id = e.player_id
where pl.slug in (select x ->> 'slug' from _r050, jsonb_array_elements(j -> 'new_players') x)
union
select e.id from public.player_evaluations e
join public.scouting_publications pub on pub.id = e.publication_id and pub.publication_slug = (select j ->> 'publication_slug' from _r050)
join public.players pl on pl.id = e.player_id
join public.player_evaluation_rankings r on r.evaluation_id = e.id
join _r050 on true
join lateral jsonb_array_elements(j -> 'dodgers_evaluations') d on d ->> 'slug' = pl.slug
where r.scope_label = d ->> 'scope_label' and e.evaluation_date = (d ->> 'evaluation_date')::date;

alter table public.player_evaluations disable trigger player_evaluations_guard;
alter table public.player_evaluation_rankings disable trigger player_evaluation_rankings_immutable;
delete from public.player_evaluation_rankings where evaluation_id in (select id from _r050_eval);
delete from public.player_evaluations where id in (select id from _r050_eval);
alter table public.player_evaluation_rankings enable trigger player_evaluation_rankings_immutable;
alter table public.player_evaluations enable trigger player_evaluations_guard;

-- ===========================================================================
-- 3. THE BENCHMARK PLAYERS, SIGNINGS, MEMBERS, AUDITS, OUTCOMES AND EVIDENCE
-- ===========================================================================

create temporary table _r050_players on commit drop as
select pl.id, pl.slug from public.players pl where pl.slug in (select x ->> 'slug' from _r050, jsonb_array_elements(j -> 'new_players') x);

delete from public.evidence where entity_type = 'signing' and entity_id in (select s.id from public.signings s where s.player_id in (select id from _r050_players));
delete from public.evidence where entity_type = 'player' and entity_id in (select id from _r050_players);
delete from public.signing_population_member_sources where member_id in (select m.id from public.signing_population_members m
  join public.signings s on s.id = m.signing_id where s.player_id in (select id from _r050_players));
delete from public.signing_population_members where signing_id in (select s.id from public.signings s where s.player_id in (select id from _r050_players));
delete from public.outcomes where player_id in (select id from _r050_players);
delete from public.outcome_audits where player_id in (select id from _r050_players);
delete from public.outcome_evidence where player_id in (select id from _r050_players);
delete from public.player_aliases where player_id in (select id from _r050_players);
delete from public.signings where player_id in (select id from _r050_players);
delete from public.players where id in (select id from _r050_players);

-- ===========================================================================
-- 4. THE LEGACY IDENTITIES: back to unresolved, exactly as 035 left them
-- ===========================================================================

create temporary table _r050_legacy on commit drop as
select pl.id, x ->> 'mlb_id' as mlb_id, x ->> 'alias' as alias
from _r050, jsonb_array_elements(j -> 'legacy') x join public.players pl on pl.slug = x ->> 'slug';

delete from public.outcomes where player_id in (select id from _r050_legacy);
delete from public.outcome_audits where player_id in (select id from _r050_legacy);
delete from public.outcome_evidence where player_id in (select id from _r050_legacy);
delete from public.evidence where entity_type = 'player' and entity_id in (select id from _r050_legacy) and field_name in ('mlb_id', 'birth_date', 'bref_id');
delete from public.player_aliases a using _r050_legacy l where a.player_id = l.id and a.alias = l.alias and a.alias_type = 'MLB_RECORD_NAME';
update public.players pl set mlb_id = null, birth_date = null, bref_id = null, mlb_debut_date = null
from _r050_legacy l where pl.id = l.id and pl.mlb_id = l.mlb_id::bigint;

-- ===========================================================================
-- 5. POPULATIONS, THE STORED EVALUATION AND THE EXECUTIVE FUNCTION
-- ===========================================================================

create temporary table _r050_cov on commit drop as
select sp.legacy_coverage_id as id from public.signing_populations sp
where sp.population_key in (select jsonb_array_elements_text(j -> 'populations') from _r050) and sp.legacy_coverage_id is not null;
delete from public.signing_populations where population_key in (select jsonb_array_elements_text(j -> 'populations') from _r050);
delete from public.signing_census_coverage where id in (select id from _r050_cov);

update public.outcome_model_evaluations m set
  model_version = x ->> 'model_version', validation_method = x ->> 'validation_method',
  feature_list = array(select jsonb_array_elements_text(x -> 'feature_list')), training_populations = array(select jsonb_array_elements_text(x -> 'training_populations')),
  evaluated_rows = (x ->> 'evaluated_rows')::int, positive_n = (x ->> 'positive_n')::int, folds = (x ->> 'folds')::int,
  brier_score = (x ->> 'brier_score')::numeric, log_loss = (x ->> 'log_loss')::numeric, auc = (x ->> 'auc')::numeric,
  brier_skill_vs_base_rate = (x ->> 'brier_skill_vs_base_rate')::numeric, calibration_bins = x -> 'calibration_bins', decision = x ->> 'decision',
  decision_reason = x ->> 'decision_reason', training_fingerprint = x ->> 'training_fingerprint', data_as_of_date = (x ->> 'data_as_of_date')::date
from _r050, jsonb_array_elements(j -> 'evaluation_041') x
where m.target_key = x ->> 'target_key' and m.model_key = x ->> 'model_key';

create or replace function public.disi_executive_overview()
returns table (
  analysis_as_of_date date, all_tracked_signings integer, total_players integer, markets_represented integer, earliest_signing_year integer,
  latest_signing_year integer, dodgers_signings integer, dodgers_tracked_or_census_signings integer, dodgers_outcome_selected_signings integer,
  mature_signings integer, verified_mlb_players integer, outcome_audits_completed integer, outcome_audit_queue integer,
  signings_with_known_cost integer, signings_with_complete_cost integer, known_acquisition_spend_usd numeric, cost_coverage numeric,
  spend_state text, signings_with_resolved_value integer, realized_direct_dodgers_bwar numeric, realized_individually_attributable_trade_bwar numeric,
  realized_org_value_bwar numeric, value_left_organization_bwar numeric, signings_with_other_club_value_known integer,
  probability_targets integer, supported_probability_targets integer, probability_rows bigint, non_null_probabilities integer,
  expected_value_models integer, supported_expected_value_models integer, supported_expected_values integer,
  predictive_portfolio_recommendations integer, supported_fitted_models integer, open_research_tasks integer,
  prediction_readiness_state text, prediction_readiness_statement text
)
language plpgsql
stable
security invoker
set search_path = ''
as $fn$
declare
  st record;
  a record;
  v_as_of date;
  v_targets int;
  v_supported_targets int;
  v_any_probability boolean;
  v_ev_models int;
  v_supported_ev_models int;
  v_any_ev boolean;
  v_probabilities int := 0;
  v_expected_values int := 0;
  v_recommendations int := 0;
  v_probability_rows bigint;
  v_fitted int;
  v_rows int;
begin
  -- coverage (v_database_status, one row)
  execute $q$
    select tracked_signings, total_players, markets_represented, earliest_signing_year, latest_signing_year, outcome_audits_completed,
      outcome_audit_queue, open_research_tasks
    from public.v_database_status
  $q$ into st;
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    return;
  end if;
  -- Dodgers signings, known spend and realized organizational value (042), components kept separate
  execute $q$
    select count(*)::int as dodgers_signings,
      count(*) filter (where population_class <> 'OUTCOME_SELECTED_SAMPLE')::int as dodgers_tracked_or_census_signings,
      count(*) filter (where population_class = 'OUTCOME_SELECTED_SAMPLE')::int as dodgers_outcome_selected_signings,
      count(*) filter (where maturity_status = 'MATURE')::int as mature_signings,
      count(*) filter (where reached_mlb_verified)::int as verified_mlb_players,
      count(known_acquisition_cost_usd)::int as signings_with_known_cost,
      count(*) filter (where cost_complete)::int as signings_with_complete_cost,
      sum(known_acquisition_cost_usd) as known_acquisition_spend_usd,
      count(*) filter (where realized_value_state in ('REALIZED_TO_DATE', 'TO_DATE_CHAIN_INCOMPLETE'))::int as signings_with_resolved_value,
      sum(direct_dodgers_bwar) filter (where realized_value_state in ('REALIZED_TO_DATE', 'TO_DATE_CHAIN_INCOMPLETE')) as direct_dodgers_bwar,
      sum(individually_attributable_trade_bwar) filter (where realized_value_state in ('REALIZED_TO_DATE', 'TO_DATE_CHAIN_INCOMPLETE')) as individually_attributable_trade_bwar,
      sum(realized_org_value_bwar) as realized_org_value_bwar,
      sum(value_left_organization_bwar) as value_left_organization_bwar,
      count(value_left_organization_bwar)::int as signings_with_other_club_value_known
    from public.v_player_realized_organizational_value
  $q$ into a;
  -- 041 probability support
  execute $q$
    select count(distinct target_key)::int, (count(distinct target_key) filter (where baseline_supported))::int,
      coalesce(bool_or(baseline_supported), false)
    from public.v_outcome_target_support
  $q$ into v_targets, v_supported_targets, v_any_probability;
  -- 042 expected-value support
  execute $q$
    select count(*)::int, (count(*) filter (where expected_value_supported))::int, coalesce(bool_or(expected_value_supported), false)
    from public.v_expected_value_support
  $q$ into v_ev_models, v_supported_ev_models, v_any_ev;
  -- per-player predictive outputs, only when their upstream support exists
  if v_any_probability then
    execute $q$ select count(probability)::int from public.v_player_outcome_probability $q$ into v_probabilities;
  end if;
  if v_any_ev then
    execute $q$ select count(expected_org_value_bwar)::int from public.v_player_expected_organizational_value $q$ into v_expected_values;
    execute $q$ select (count(*) filter (where optimization_eligible))::int from public.v_portfolio_candidate_readiness $q$ into v_recommendations;
  end if;
  execute $q$ select max(audited_through_date) from public.outcome_audits $q$ into v_as_of;
  execute $q$ select (select count(*) from public.signings) * (select count(*) from public.outcome_targets) $q$ into v_probability_rows;
  execute $q$ select count(*)::int from public.outcome_model_evaluations where decision = 'MODEL_SUPPORTED' $q$ into v_fitted;
  return query select
    v_as_of,
    st.tracked_signings, st.total_players, st.markets_represented, st.earliest_signing_year, st.latest_signing_year,
    a.dodgers_signings, a.dodgers_tracked_or_census_signings, a.dodgers_outcome_selected_signings, a.mature_signings, a.verified_mlb_players,
    st.outcome_audits_completed, st.outcome_audit_queue,
    a.signings_with_known_cost, a.signings_with_complete_cost, round(a.known_acquisition_spend_usd, 2),
    round(a.signings_with_known_cost::numeric / nullif(a.dodgers_signings, 0), 3),
    case when a.signings_with_complete_cost < a.dodgers_signings then 'KNOWN_SPEND_IS_A_LOWER_BOUND' else 'SPEND_COMPLETE' end,
    a.signings_with_resolved_value,
    round(a.direct_dodgers_bwar, 2),
    round(a.individually_attributable_trade_bwar, 2),
    round(a.realized_org_value_bwar, 2),
    round(a.value_left_organization_bwar, 2), a.signings_with_other_club_value_known,
    v_targets, v_supported_targets, v_probability_rows, v_probabilities,
    v_ev_models, v_supported_ev_models, v_expected_values, v_recommendations,
    v_fitted,
    st.open_research_tasks,
    case when v_any_probability then 'PROBABILITIES_PUBLISHED_FOR_SUPPORTED_TARGETS' else 'NO_SUPPORTED_PROBABILITY_TARGET' end,
    case when v_any_probability
         then 'DISI publishes outcome probabilities only for targets whose reference population meets the minimum support threshold; see Prediction readiness.'
         else 'DISI does not currently publish player outcome probabilities because the verified mature sample does not meet the minimum support threshold.' end;
end
$fn$;

create or replace function public.disi_refresh_product_snapshots()
returns table (snapshot text, row_count integer, elapsed_ms integer)
language plpgsql
volatile
security invoker
set search_path = ''
as $fn$
declare
  v_gen bigint;
  v_t timestamptz;
  v_n int;
  v_bad text;
begin
  -- one refresh at a time; EXCLUSIVE mode still lets readers (ACCESS SHARE) read the previous generation until this transaction commits
  lock table public.product_executive_snapshot in exclusive mode;
  select coalesce(max(generation_id), 0) + 1 into v_gen from public.product_executive_snapshot;
  -- each snapshot is its own statement: planned when it runs and released when it ends (the analytical views are staged since 043a)
  -- product_executive_snapshot
  v_t := clock_timestamp();
  execute 'delete from public.product_executive_snapshot';
  execute $q$
    insert into public.product_executive_snapshot
    select $1, x.* from (
      select current_timestamp as generated_at, (current_timestamp at time zone 'UTC')::date as snapshot_as_of_date,
          rs.analysis_as_of_date as source_data_as_of_date, rs.latest_development_data_date as source_development_data_as_of_date,
          rs.product_version, rs.schema_version, rs.support_chain_state, o.*,
          rs.canonical_through, rs.latest_outcome_audit_date, rs.model_evaluation_data_as_of, rs.probability_model_version, rs.value_model_version,
          rs.decision_engine_version, rs.product_contract_relations, rs.product_statement
        from public.v_executive_overview o cross join public.v_disi_release_status rs
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_executive_snapshot'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- product_prediction_readiness
  v_t := clock_timestamp();
  execute 'delete from public.product_prediction_readiness';
  execute $q$
    insert into public.product_prediction_readiness
    select $1, x.* from (
      select * from public.v_prediction_readiness
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_prediction_readiness'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- product_model_evaluations
  v_t := clock_timestamp();
  execute 'delete from public.product_model_evaluations';
  execute $q$
    insert into public.product_model_evaluations
    select $1, x.* from (
      select * from public.v_outcome_model_evaluation
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_model_evaluations'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- product_expected_value_support
  v_t := clock_timestamp();
  execute 'delete from public.product_expected_value_support';
  execute $q$
    insert into public.product_expected_value_support
    select $1, x.* from (
      select * from public.v_expected_value_support
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_expected_value_support'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- product_portfolio_decision_support
  v_t := clock_timestamp();
  execute 'delete from public.product_portfolio_decision_support';
  execute $q$
    insert into public.product_portfolio_decision_support
    select $1, x.* from (
      select * from public.v_portfolio_decision_support
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_portfolio_decision_support'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- product_portfolio_history
  v_t := clock_timestamp();
  execute 'delete from public.product_portfolio_history';
  execute $q$
    insert into public.product_portfolio_history
    select $1, x.* from (
      select * from public.v_historical_portfolio_summary
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_portfolio_history'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- product_portfolio_scenarios
  v_t := clock_timestamp();
  execute 'delete from public.product_portfolio_scenarios';
  execute $q$
    insert into public.product_portfolio_scenarios
    select $1, x.* from (
      select * from public.v_portfolio_scenario_evaluation
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_portfolio_scenarios'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- product_player_decision
  v_t := clock_timestamp();
  execute 'delete from public.product_player_decision';
  execute $q$
    insert into public.product_player_decision
    select $1, x.* from (
      select r.*, c.decision_as_of_date, c.decision_support_state, c.optimization_eligible, c.decision_blockers, c.decision_statement,
          c.expected_value_model_supported, c.historical_comparables, c.cost_complete as readiness_cost_complete,
          c.cost_coverage_state as readiness_cost_coverage_state, c.player_data_complete
        from public.v_player_realized_organizational_value r
        left join public.v_portfolio_candidate_readiness c on c.signing_id = r.signing_id
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_player_decision'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- product_player_expected_value
  v_t := clock_timestamp();
  execute 'delete from public.product_player_expected_value';
  execute $q$
    insert into public.product_player_expected_value
    select $1, x.* from (
      select * from public.v_player_expected_organizational_value
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_player_expected_value'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- product_player_comparables
  v_t := clock_timestamp();
  execute 'delete from public.product_player_comparables';
  execute $q$
    insert into public.product_player_comparables
    select $1, x.* from (
      select s.* from public.v_player_comparable_summary s
        where s.target_signing_id in (select signing_id from public.v_player_realized_organizational_value)
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_player_comparables'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- product_database_status
  v_t := clock_timestamp();
  execute 'delete from public.product_database_status';
  execute $q$
    insert into public.product_database_status
    select $1, x.* from (
      select e.generated_at, e.source_data_as_of_date, e.product_version, e.schema_version, s.*
        from public.v_database_status s cross join public.product_executive_snapshot e
    ) x
  $q$ using v_gen;
  get diagnostics v_n = row_count;
  snapshot := 'product_database_status'; row_count := v_n; elapsed_ms := (extract(epoch from clock_timestamp() - v_t) * 1000)::int;
  return next;
  -- validate the new generation before it can commit; every rule is derived from the snapshot itself, none is a fixed answer
  execute $q$
    with e as (select * from public.product_executive_snapshot)
    select concat_ws('; ',
      case when (select count(*) from e) <> 1 then 'executive snapshot is not one row' end,
      case when exists (select 1 from e where e.dodgers_signings <> (select count(distinct signing_id) from public.product_player_decision)) then 'player snapshot does not cover every Dodgers signing' end,
      case when exists (select 1 from e where e.supported_probability_targets <> (select count(distinct target_key) from public.product_prediction_readiness where baseline_supported)) then 'supported targets disagree with prediction readiness' end,
      case when exists (select 1 from e where e.supported_expected_value_models <> (select count(*) from public.product_expected_value_support where expected_value_supported)) then 'supported value models disagree with expected-value support' end,
      case when exists (select 1 from e where e.supported_expected_values <> (select count(expected_org_value_bwar) from public.product_player_expected_value)) then 'supported expected values disagree with the player snapshot' end,
      case when exists (select 1 from e where e.predictive_portfolio_recommendations <> (select count(*) from public.product_player_decision where optimization_eligible)) then 'recommendations disagree with the player snapshot' end,
      case when exists (select 1 from e where (e.supported_probability_targets = 0) <> (e.support_chain_state = 'NO_PREDICTIVE_LAYER_SUPPORTED')) then 'support-chain state disagrees with probability support' end,
      case when exists (select 1 from e where e.supported_probability_targets = 0 and e.supported_expected_value_models > 0) then 'expected value supported without probability support' end,
      case when exists (select 1 from e where e.supported_expected_value_models = 0 and (e.supported_expected_values > 0 or e.predictive_portfolio_recommendations > 0)) then 'predictive outputs without a supported value model' end,
      case when exists (select 1 from public.product_portfolio_scenarios where optimized_selection is not null and optimization_eligible_candidates = 0) then 'optimized selection without eligible candidates' end,
      case when exists (select 1 from public.product_player_expected_value where expected_org_value_bwar is not null and not expected_value_supported) then 'expected value published for an unsupported row' end,
      case when (select count(*) from public.product_database_status) <> 1 then 'status snapshot is not one row' end,
      case when exists (select 1 from e join public.product_database_status s on s.tracked_signings is distinct from e.dodgers_signings) then 'status snapshot disagrees with the executive snapshot' end
    )
  $q$ into v_bad;
  if v_bad <> '' then
    raise exception 'product snapshot refresh refused (generation %): %', v_gen, v_bad;
  end if;
end
$fn$;

-- ===========================================================================
-- 6. POSTCONDITIONS AND ONE REFRESH
-- ===========================================================================

do $$
declare
  k text;
begin
  if (select count(*) from public.players) <> (select (j #>> '{baseline,counts,players}')::int from _r050)
     or (select count(*) from public.signings where record_scope = 'MLB_PIPELINE_TOP_PROSPECT') <> (select (j #>> '{baseline,counts,benchmark_signings}')::int from _r050)
     or (select count(*) from public.outcome_audits) <> (select (j #>> '{baseline,counts,outcome_audits}')::int from _r050)
     or (select count(*) from public.outcomes) <> (select (j #>> '{baseline,counts,outcomes}')::int from _r050)
     or (select count(*) from public.player_evaluations) <> (select (j #>> '{baseline,counts,player_evaluations}')::int from _r050)
     or (select count(*) from public.signing_populations) <> (select (j #>> '{baseline,counts,signing_populations}')::int from _r050)
     or (select count(*) from public.signing_population_members) <> (select (j #>> '{baseline,counts,population_members}')::int from _r050)
     or (select count(*) from public.signing_census_coverage) <> (select (j #>> '{baseline,counts,census_coverage_rows}')::int from _r050) then
    raise exception 'rollback-050 postcondition: the pre-050 counts are not restored';
  end if;
  if exists (select 1 from public.outcome_model_evaluations where training_fingerprint <> (select j #>> '{baseline,evaluation,0,training_fingerprint}' from _r050)) then
    raise exception 'rollback-050 postcondition: the stored 041 evaluation is not restored';
  end if;
  select md5(prosrc) into k from pg_proc where proname = 'disi_executive_overview' and pronamespace = 'public'::regnamespace;
  if k is distinct from (select j #>> '{executive,old_md5}' from _r050) then
    raise exception 'rollback-050 postcondition: disi_executive_overview() is not the 044 definition';
  end if;
  select md5(prosrc) into k from pg_proc where proname = 'disi_refresh_product_snapshots' and pronamespace = 'public'::regnamespace;
  if k is distinct from (select j #>> '{refresh,old_md5}' from _r050) then
    raise exception 'rollback-050 postcondition: disi_refresh_product_snapshots() is not the 045b definition';
  end if;
  if exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid where c.relname in ('player_evaluations', 'player_evaluation_rankings')
             and not t.tgisinternal and t.tgenabled <> 'O') then
    raise exception 'rollback-050 postcondition: an evaluation guard trigger is not enabled';
  end if;
end $$;

select * from public.disi_refresh_product_snapshots();

commit;
